const filtro = (columnName, condition, value) => ({ filter: { type: "and", filters: [{ columnName, condition, value }] } });
n8nApi.filasOk(p, t, filtro("edad", "gt", 30)).then((f) => expect(f.map((x) => x.edad)).to.deep.equal([45]));
